import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        if n == 0:
            results.append("0")
            continue

        inc_ends = []
        dec_ends = []
        inc_seqs = []
        dec_seqs = []

        for x in a:
            placed = False

            best_inc_idx = -1
            best_inc_val = float('inf')

            for i, val in enumerate(inc_ends):
                if val < x:
                    if val > best_inc_val:
                        best_inc_val = val
                        best_inc_idx = i

            if best_inc_idx != -1:
                inc_ends[best_inc_idx] = x
                inc_seqs[best_inc_idx].append(x)
                placed = True

            if not placed:
                best_dec_idx = -1
                best_dec_val = float('-inf')

                for i, val in enumerate(dec_ends):
                    if val > x:
                        if val < best_dec_val:
                            best_dec_val = val
                            best_dec_idx = i

                if best_dec_idx != -1:
                    dec_ends[best_dec_idx] = x
                    dec_seqs[best_dec_idx].append(x)
                    placed = True

            if not placed:
                inc_ends.append(x)
                inc_seqs.append([x])

        all_seqs = inc_seqs + dec_seqs
        k = len(all_seqs)

        res_lines = [str(k)]
        for seq in all_seqs:
            line_parts = [str(len(seq))] + [str(v) for v in seq]
            res_lines.append(" ".join(line_parts))

        results.append("\n".join(res_lines))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
